class PackageApp:public OrganicApplication{public:PackageApp():OrganicApplication("Midnight package software acceptance",false){}void initialiseInternal(const String&)override{}};
static int checks=0;static void check(bool ok,const char* s){if(!ok)throw std::runtime_error(s);++checks;std::cout<<"PASS "<<s<<std::endl;}
static void pump(int ms){auto until=monotonic()+ms*.001;while(monotonic()<until){MSG m;while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}Thread::sleep(1);}}
static void wait(Coordinator& c,std::function<bool()> f,const char* s){auto until=monotonic()+4;while(!f()&&monotonic()<until){pump(10);c.tick();}check(f(),s);}
static var object(){return var(new DynamicObject());}
static var copy(const var& v){return JSON::parse(JSON::toString(v));}
static void bind(Cue& cue,const char* alias,const char* kind,const String& value){if(!cue.aliases.isObject())cue.aliases=object();auto ref=object();ref.getDynamicObject()->setProperty("kind",kind);ref.getDynamicObject()->setProperty(String(kind)=="parameter"?"address":"id",value);cue.aliases.getDynamicObject()->setProperty(alias,ref);}
static var code(var bundle,const String& text){bundle=copy(bundle);MemoryBlock bytes(text.toRawUTF8(),text.getNumBytesAsUTF8());bundle["files"].getDynamicObject()->setProperty(Identifier(bundle["manifest"]["entry"].toString()),bytes.toBase64Encoding());bundle.getDynamicObject()->setProperty("sha256",packageHash(bundle));return bundle;}
int main(int argc,char** argv){if(argc!=2)return 2;ScopedJuceInitialiser_GUI gui;PackageApp app;app.engine.reset(new ChataigneEngine());app.engine->createNewGraph();int result=0;try{
 auto root=File(String::fromUTF8(argv[1]));auto finite=importPackage(root.getChildFile("finite-light"));auto persistent=importPackage(root.getChildFile("persistent-light"));auto movement=importPackage(root.getChildFile("finite-movement"));
 auto* group=new CVGroup("Package fixture");CVGroupManager::getInstance()->addItem(group);auto variable=[&](const char* name,double v){auto* p=new FloatParameter(name,"Software only",float(v),0,1);group->values.addItem(new GenericControllableItem(p));return p;};auto* light=variable("Light A",0);auto* second=variable("Light B",0);auto* sensor=variable("Sensor",.2);
 Coordinator c(false);auto cue=c.add(CueType::Package);cue->package=finite;bind(*cue,"light","parameter",light->getControlAddress());pump(50);check(light->doubleValue()==0&&c.runs.empty(),"C1 package import and schema inspection execute no code or outputs");
 auto bad=copy(finite);bad["manifest"].getDynamicObject()->setProperty("apiVersion",99);bool rejected=false;try{validatePackage(bad);}catch(...){rejected=true;}check(rejected,"C1 unsupported API rejected without execution");bad=copy(finite);bad["manifest"].getDynamicObject()->setProperty("entry","../escape.js");bad.getDynamicObject()->setProperty("sha256",packageHash(bad));rejected=false;try{validatePackage(bad);}catch(...){rejected=true;}check(rejected,"C1 escaping relative asset rejected");bad=copy(finite);bad["files"].getDynamicObject()->setProperty("note.txt","altered");rejected=false;try{validatePackage(bad);}catch(...){rejected=true;}check(rejected,"C1 changed embedded bytes rejected by integrity validation");
 auto id=c.direct(cue->id);auto run=c.runs[id];auto hash=run->package->hash;wait(c,[&]{return run->outcome==Outcome::Succeeded;},"C3 finite package completes only after acknowledged light request");check(std::abs(light->doubleValue()-.6)<1e-5,"finite package requests ordinary native parameter output");check(!run->package->isOpen(),"C5 finite completion closes further script output admission");cue->package=code(finite,"function onStart(c) { host.request('light', 0.1); host.complete(); }");check(run->package->hash==hash,"C1 active package retains pinned original code/parameter hash");
 auto cp=c.find(c.duplicate(cue->id));bind(*cp,"light","parameter",second->getControlAddress());auto copyId=c.direct(cp->id);wait(c,[&]{return c.runs[copyId]->outcome==Outcome::Succeeded;},"C3 copied package has independent worker and alias binding");check(std::abs(light->doubleValue()-.6)<1e-5&&std::abs(second->doubleValue()-.1)<1e-5,"C3 copied package writes only its bound target");
 auto live=c.add(CueType::Package);live->package=persistent;bind(*live,"light","parameter",light->getControlAddress());bind(*live,"sensor","parameter",sensor->getControlAddress());auto liveId=c.direct(live->id);auto liveRun=c.runs[liveId];wait(c,[&]{return light->doubleValue()==0&&liveRun->package->isOpen();},"C3 persistent package remains active after start/input callbacks return");sensor->setValue(.9);wait(c,[&]{return std::abs(light->doubleValue()-.8)<1e-5;},"persistent package processes captured input on serialized worker");auto old=liveRun->package;c.end(liveId);auto values=object();values.getDynamicObject()->setProperty("sensor",0);old->frame(monotonic()+10,10,true,values);old->requestResult(999,true,"late");sensor->setValue(.1);pump(60);c.tick();check(std::abs(light->doubleValue()-.8)<1e-5&&!old->isOpen(),"C2 delayed input/result/timer callbacks after End produce no output");auto again=c.direct(live->id,true);wait(c,[&]{return light->doubleValue()==0;},"C2 new package generation starts from current input");c.end(liveId,liveRun->generation);check(c.runs[again]->package->isOpen(),"C2 old End does not close replacement worker");c.end(again);
 auto timeout=c.add(CueType::Package);timeout->package=code(finite,"function onStart(c) { while (true) {} }");bind(*timeout,"light","parameter",light->getControlAddress());auto tid=c.direct(timeout->id);wait(c,[&]{return c.runs[tid]->outcome==Outcome::Failed;},"C4 pure JavaScript non-returning loop hits cooperative budget");check(!c.runs[tid]->package->isOpen(),"C4 timed-out program closes output admission");
 auto forbidden=c.add(CueType::Package);forbidden->package=code(finite,"function onStart(c) { host.request('undeclared', 1); }");bind(*forbidden,"light","parameter",light->getControlAddress());auto fid=c.direct(forbidden->id);wait(c,[&]{return c.runs[fid]->outcome==Outcome::Failed;},"C5 undeclared output capability rejected before dispatch");
 auto missing=c.add(CueType::Package);missing->package=finite;bind(*missing,"light","parameter","/missing/target");auto mid=c.direct(missing->id);check(c.runs[mid]->outcome==Outcome::Failed,"C5 missing alias target fails scoped Start");
 Document doc;Adapter bus;bus.id="fake";bus.simulated=true;doc.adapters={bus};for(int n=1;n<=2;++n){Motor m;m.id="M"+std::to_string(n);m.can=n;m.adapter=bus.id;m.min=-90;m.max=90;doc.motors.push_back(m);}service()->edit(doc);wait(c,[&]{return service()->snapshot().motors["M1"].at>=0;},"fake motor feedback available for package child ownership");auto authored=c.add(CueType::Motion);auto b=authored->actions[0];b->motor->select("M1");b->duration->setValue(.12);b->startAngle->setValue(0);b->target->setValue(5);b->playCurve->setValue(true);auto owned=c.add(CueType::Package);owned->package=movement;bind(*owned,"movement","cue",String(authored->id));auto oid=c.direct(owned->id);auto orr=c.runs[oid];wait(c,[&]{return orr->package->logicComplete;},"C3 finite logic can finish before required motor child");check(orr->outcome==Outcome::Pending,"C3 package aggregate does not confuse logic completion with motor arrival");wait(c,[&]{return orr->outcome==Outcome::Succeeded;},"C3 required motor child releases aggregate success after native completion");check(c.owns(*orr),"C3 successful package retains exact held motor child");c.end(oid);check(service()->snapshot().motors["M1"].owner.empty(),"C3 exact package End releases held child");
 auto brokenStop=c.add(CueType::Package);brokenStop->package=code(movement,"function onStart(c) { host.request('movement',0); } function onStop(c,reason) { missingStopFunction(); }");brokenStop->package["manifest"].getDynamicObject()->setProperty("lifetime","persistent");brokenStop->package.getDynamicObject()->setProperty("sha256",packageHash(brokenStop->package));bind(*brokenStop,"movement","cue",String(authored->id));auto bs=c.direct(brokenStop->id);wait(c,[&]{return !service()->snapshot().motors["M1"].owner.empty();},"C4 persistent package owns a native child before End");Event unrelated;unrelated.id="unrelated-package-fixture";unrelated.outputs={"M2"};unrelated.target=7;service()->launch(unrelated);c.end(bs);check(service()->snapshot().motors["M1"].owner.empty()&&service()->snapshot().motors["M2"].owner==unrelated.id,"C4 declarative cleanup occurs before stop hook and preserves unrelated work");wait(c,[&]{return c.runs[bs]->package->failed;},"C4 failed stop hook reported after exact cleanup");service()->end(unrelated.id);

 auto never=c.add(CueType::Package);never->package=code(movement,"function onStart(c) { host.complete(); }");bind(*never,"movement","cue",String(authored->id));auto neverId=c.direct(never->id);wait(c,[&]{return c.runs[neverId]->outcome==Outcome::Failed;},"C5 required native alias cannot silently complete without launching");
 auto delayed=c.add(CueType::Package);delayed->package=movement;bind(*delayed,"movement","cue",String(authored->id));delayed->pre->setValue(.12);auto delayedId=c.direct(delayed->id);authored->actions[0]->target->setValue(40);c.erase(authored->id);wait(c,[&]{return c.runs[delayedId]->package&&c.runs[delayedId]->package->logicComplete;},"C1 package alias keeps accepted movement snapshot through edit/deletion during pre-wait");check(c.runs[delayedId]->package->bindings["movement"].event.target==5,"C1 later definition edits do not change package child endpoint");c.end(delayedId);
 auto saved=c.save();c.clear();c.load(saved);check(c.runs.empty(),"C1 package definitions assets and parameters reopen inertly");check(c.find(cue->id)->package["files"].isObject(),"C1 package assets persist with the show");
 std::cout<<"SUCCESS "<<checks<<" package checks"<<std::endl;
 }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<std::endl;result=1;}app.engine.reset();return result;}
